  function mapXml.spawnSource(map)
    local xml = mapXml.source(map)
    local properties = xml:match('<P%s+[^>]*>') or ''
    local layout = layouts[mapXml.attribute(properties, 'volleySpawns')]
    if layout and tonumber(mapXml.attribute(properties, 'L')) == layout.width then
      return layout.markers
    end
    return xml
  end
